},{"id":"spl-dsp-pioneer-deq-1000a","category":"DSP","brand":"Pioneer","model":"DEQ-1000A","isActive":true,"lifecycle":"DISCONTINUED","sourceType":"MANUFACTURER_CATALOG","sourceUrl":"https://pioneercarentertainment.com/catalogue/"},{"id":"spl-dsp-pioneer-deq-s1000a","category":"DSP","brand":"Pioneer","model":"DEQ-S1000A","isActive":true,"lifecycle":"UNKNOWN","sourceType":"MANUFACTURER_CATALOG","sourceUrl":"https://pioneercarentertainment.com/catalogue/"},{"id":"spl-dsp-taramps-pro-2-4s","category":"DSP","brand":"Taramps","model":"Pro 2.4S","isActive":true,"lifecycle":"UNKNOWN","sourceType":"MANUFACTURER_CATALOG","sourceUrl":"https://www.taramps.com.br/"},{"id":"spl-dsp-taramps-dsp-2-6","category":"DSP","brand":"Taramps","model":"DSP 2.6","isActive":true,"lifecycle":"UNKNOWN","sourceType":"MANUFACTURER_CATALOG","sourceUrl":"https://www.taramps.com.br/"},{"id":"spl-dsp-deaf-bonce-machete-dsp-2-8","category":"DSP","brand":"Deaf Bonce","model":"Machete DSP 2.8","isActive":true,"lifecycle":"UNKNOWN","sourceType":"MANUFACTURER_CATALOG","sourceUrl":"https://deafbonce.com/"},{"id":"spl-dsp-deaf-bonce-apocalypse-dsp-8","category":"DSP","brand":"Deaf Bonce","model":"Apocalypse DSP-8","isActive":true,"lifecycle":"UNKNOWN","sourceType":"MANUFACTURER_CATALOG","sourceUrl":"https://deafbonce.com/"}]}'::jsonb AS data),
current AS (SELECT "id", COALESCE("catalogs",'{}'::jsonb) AS catalogs FROM "SiteSettings" WHERE "id"='default'),
updated AS (
 SELECT current."id",
 jsonb_set(
   jsonb_set(current.catalogs,'{componentBrands}',
     COALESCE((SELECT jsonb_agg(
       CASE WHEN (item->>'category') IN ('BATTERY','GENERATOR','WIRING','ACCESSORY')
              OR NOT (
                ((item->>'category')='HEAD_UNIT' AND lower(item->>'name') IN ('pioneer','alpine','kenwood','jvc','sony','clarion'))
                OR ((item->>'category')='AUDIO_COMPONENT' AND lower(item->>'name') IN ('pride','deaf bonce','avatar','ground zero','sundown audio','dd audio','dynamic state','ural','dl audio','b2 audio','american bass'))
                OR ((item->>'category')='SUBWOOFER' AND lower(item->>'name') IN ('deaf bonce','pride','avatar','ground zero','sundown audio','dd audio','american bass','b2 audio'))
                OR ((item->>'category')='AMPLIFIER' AND lower(item->>'name') IN ('sundown audio','dd audio','taramps','deaf bonce','ground zero','pride','b2 audio','american bass'))
                OR ((item->>'category')='DSP' AND lower(item->>'name') IN ('helix','match','audison','ground zero','pioneer','taramps','deaf bonce'))
              )
            THEN jsonb_set(item,'{isActive}','false'::jsonb,true)
            ELSE item END
       ORDER BY item->>'category',item->>'name')
       FROM (
               SELECT DISTINCT ON (lower(item->>'category'), lower(item->>'name')) item
               FROM (SELECT jsonb_array_elements(COALESCE(current.catalogs->'componentBrands','[]'::jsonb)) item
                     UNION ALL SELECT jsonb_array_elements(seed.data->'brands') item) raw_brands
               ORDER BY lower(item->>'category'), lower(item->>'name'),
                        CASE WHEN item->>'isActive'='true' THEN 0 ELSE 1 END,
                        CASE WHEN item->>'sourceType'='MANUFACTURER_CATALOG' THEN 0 ELSE 1 END
             ) all_brands), '[]'::jsonb), true),
   '{componentModels}',
     COALESCE((SELECT jsonb_agg(
       CASE WHEN (item->>'category') IN ('BATTERY','GENERATOR','WIRING','ACCESSORY')
              OR NOT (
                ((item->>'category')='HEAD_UNIT' AND lower(item->>'brand') IN ('pioneer','alpine','kenwood','jvc','sony','clarion'))
                OR ((item->>'category')='AUDIO_COMPONENT' AND lower(item->>'brand') IN ('pride','deaf bonce','avatar','ground zero','sundown audio','dd audio','dynamic state','ural','dl audio','b2 audio','american bass'))
                OR ((item->>'category')='SUBWOOFER' AND lower(item->>'brand') IN ('deaf bonce','pride','avatar','ground zero','sundown audio','dd audio','american bass','b2 audio'))
                OR ((item->>'category')='AMPLIFIER' AND lower(item->>'brand') IN ('sundown audio','dd audio','taramps','deaf bonce','ground zero','pride','b2 audio','american bass'))
                OR ((item->>'category')='DSP' AND lower(item->>'brand') IN ('helix','match','audison','ground zero','pioneer','taramps','deaf bonce'))
              )
            THEN jsonb_set(item,'{isActive}','false'::jsonb,true)
            ELSE item END
       ORDER BY item->>'category',item->>'brand',item->>'model')
       FROM (
               SELECT DISTINCT ON (lower(item->>'category'), lower(item->>'brand'), lower(item->>'model')) item
               FROM (SELECT jsonb_array_elements(COALESCE(current.catalogs->'componentModels','[]'::jsonb)) item
                     UNION ALL SELECT jsonb_array_elements(seed.data->'models') item) raw_models
               ORDER BY lower(item->>'category'), lower(item->>'brand'), lower(item->>'model'),
                        CASE WHEN item->>'isActive'='true' THEN 0 ELSE 1 END,
                        CASE WHEN item->>'sourceType'='MANUFACTURER_CATALOG' THEN 0 ELSE 1 END
             ) all_models), '[]'::jsonb), true)
 ) catalogs
 FROM current, seed
)
UPDATE "SiteSettings" s SET "catalogs"=updated.catalogs FROM updated WHERE s."id"=updated."id";
